def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.171.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.170.0"' not in init:
        sys.exit("ABORT: not at v3.170.0.")
    for k in ("payroll_run", "payslips"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("PAY3", LESSONS_P3, QUESTIONS_P3, 9) + _validate("PAY4", LESSONS_P4, QUESTIONS_P4, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("PAY 3", LESSONS_P3, QUESTIONS_P3, "payroll_run",
         "The pay run in ZhiftERP: the Payroll Entry lifecycle across five stations; the six-line pre-run checklist and the records close; generation — company, posting date, period, filters, Get Employees, Create Salary Slips, the one-run rule; the draft review's three checks (headcount reconciliation, register comparison, spot-check slips); submission, the accrual Journal Entry, the posting tie before payment, and the custody sweep; the bank entry and payment under the separation with the three-way total; the five-line close; and the correction and off-cycle lanes."),
        ("PAY 4", LESSONS_P4, QUESTIONS_P4, "payslips",
         "The payslip in ZhiftERP: the slip as the employee's statement and the publisher-not-author custody; the slip's anatomy including working days versus payment days and the YTD block; the print format with the specimen and second-reader disciplines; Payroll Settings' delivery machinery — Email Salary Slip to Employee, Encrypt Salary Slips in Emails — with its dependencies and the one-person test; the payday calendar and the five-step query procedure; the access matrix and employee self-service; and the six confidentiality working rules."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.170.0"', '"3.171.0"'))
    print("  data: PAYROLL 3 + 4 lessons + banks REPLACED (style v3, product-first)")
    print("wrote __version__ -> 3.171.0")


if __name__ == "__main__":
    main()
